const payload = $json.body || $json;
if (!payload.destination || typeof payload.destination !== 'string') throw new Error('destination is required');
if (payload.email && payload.consent !== true) throw new Error('consent is required');
const name = String(payload.name || 'fellow traveler');
const destination = String(payload.destination);
const email_subject = 'Your SmartTrip AI Travel Request';
const email_body = `Hi ${name},
Thank you for using SmartTrip AI.
Your travel request for ${destination} has been received. Recommendations are being prepared around your preferences.
Destination: ${destination}
Travel dates: ${payload.travel_dates || 'Not selected'}
Budget: ${payload.budget || 'Not specified'} EUR
Travel style: ${payload.travel_style || 'Not specified'}
We look forward to helping you plan your next adventure.
SmartTrip AI`;
return [{json: {...payload, email_subject, email_body, status: 'received'}}];
